      Invoker.processFiles(files, verbose, args['timings'], options)
      Invoker.exit(failureLevel)
    } else {
      this.showHelp()
      process.exit(0)
    }
  }

  showHelp () {
    if (this.options.args['help'] === 'syntax') {
      console.log(fs.readFileSync(ospath.join(__dirname, '..', 'data', 'reference', 'syntax.adoc'), 'utf8'))
    } else {
